-- ----------------------------------------------------------------------------
-- Engines: The execution engines the page can be computed by. Each is a build output of this rulebook.
-- ----------------------------------------------------------------------------
INSERT INTO engines (engine_id, label, substrate, is_default, description, sort_order)
VALUES ('postgres', 'Postgres views', 'effortless-postgres', TRUE, 'Every value is a column of a generated view; the database computes it when the page reads it.', 1) ON CONFLICT (engine_id) DO UPDATE SET label = EXCLUDED.label, substrate = EXCLUDED.substrate, is_default = EXCLUDED.is_default, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order;

